"use client"

import * as React from "react"
import { Switch as SwitchPrimitive } from "@base-ui/react/switch"

import { cn } from "@/lib/utils"

// Ledger Light Switch — recessed muted track when off; checked track becomes
// the primary blue chip (same rim + soft glow as the Button).

// Base UI className can be a state function; the wrapper feeds it to cn(), so
// narrow it to a plain string (same treatment as the other ported files).
type WithClassName<P> = Omit<P, "className"> & { className?: string }

const Switch = React.forwardRef<
  React.ElementRef<typeof SwitchPrimitive.Root>,
  WithClassName<SwitchPrimitive.Root.Props>
>(({ className, ...props }, ref) => (
  <SwitchPrimitive.Root
    className={cn(
      "group/switch peer inline-flex h-5 w-9 shrink-0 cursor-pointer items-center rounded-full",
      "border border-transparent",
      "transition-all duration-fast ease-out",
      "focus-visible:outline-none focus-visible:ring-[0.1875rem] focus-visible:ring-ring/30",
      "data-disabled:cursor-not-allowed data-disabled:opacity-50",
      "data-unchecked:bg-muted data-unchecked:shadow-[var(--shadow-inset)]",
      "data-checked:bg-primary data-checked:border-[var(--primary-rim)]",
      "data-checked:shadow-[var(--shadow-primary-control)]",
      className
    )}
    {...props}
    ref={ref}
  >
    <SwitchPrimitive.Thumb
      className={cn(
        "pointer-events-none block h-4 w-4 rounded-full bg-card shadow-[var(--shadow-soft)] ring-0",
        "data-unchecked:translate-x-0.5",
        "data-checked:translate-x-[1.125rem]",
        "origin-left data-checked:origin-right rtl:origin-right rtl:data-checked:origin-left transition-[translate,scale,transform-origin,background-color,box-shadow] duration-[260ms,140ms,0ms,150ms,150ms] delay-[0ms,0ms,140ms,0ms,0ms] ease-out motion-safe:group-active/switch:scale-x-[1.18] motion-reduce:transition-none"
      )}
    />
  </SwitchPrimitive.Root>
))
Switch.displayName = "Switch"

export { Switch }
